      const problems: string[] = [];
      const positive = fields.filter((field) => forms.includes(field.form) && field.tabIndex > 0);
      if (positive.length > 0) problems.push('positive tabindex on /category/special-tools, which overrides the reading order: ' + positive.map((field) => '"' + field.name + '" (' + field.tabIndex + ')').join(', '));
      const visited: number[] = [];
