          const heading = headings.filter((candidate) => candidate.compareDocumentPosition(choice) & Node.DOCUMENT_POSITION_FOLLOWING).pop();
          const title = heading ? 'the heading "' + (heading.textContent ?? '').replace(/\s+/g, ' ').trim() + '"' : '';
